\frac{2m+8}{3}-\frac{3}{2-m}&=\frac{(2m+8)(2-m)}{3(2-m)}-\frac{3 \cdot 3}{3(2-m)}\\
&=\frac{(2m+8)(2-m)-9}{3(2-m)}.
\end{align*} Next, we can distribute $(2m+8)$ and simplify the numerator: \begin{align*}
(2m+8)(2-m)-9&=4m-2m^2+16-8m-9\\
&=-2m^2-4m+16-9\\
&=-2m^2-4m+7.
\end{align*} Therefore, we can simplify the expression as follows: \begin{align*}
\frac{(2m+8)(2-m)-9}{3(2-m)}&=\frac{-2m^2-4m+7}{3(2-m)}\\
&=\boxed{\frac{-2m^2-4m+7}{3(2-m)}}.
\end{align*}

